package android.graphics;
import java.awt.image.BufferedImage;
public class Bitmap {
 public enum CompressFormat{JPEG,PNG}
 public static Bitmap createBitmap(int w,int h,Config c){return new Bitmap(new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB_PRE));}
 public Bitmap copy(Config config,boolean mutable){BufferedImage b=new BufferedImage(getWidth(),getHeight(),BufferedImage.TYPE_INT_ARGB_PRE);java.awt.Graphics2D g=b.createGraphics();g.drawImage(image,0,0,null);g.dispose();return new Bitmap(b);}
 public void getPixels(int[] pixels,int offset,int stride,int x,int y,int w,int h){image.getRGB(x,y,w,h,pixels,offset,stride);}
 public int getPixel(int x,int y){return image.getRGB(x,y);}
 public void recycle(){}
 public void eraseColor(int color){java.awt.Graphics2D g=image.createGraphics();g.setComposite(java.awt.AlphaComposite.Src);g.setColor(new java.awt.Color(color,true));g.fillRect(0,0,getWidth(),getHeight());g.dispose();}
 public boolean compress(CompressFormat format,int quality,java.io.OutputStream out){try{BufferedImage b=image;if(format==CompressFormat.JPEG){b=new BufferedImage(getWidth(),getHeight(),BufferedImage.TYPE_INT_RGB);java.awt.Graphics2D g=b.createGraphics();g.drawImage(image,0,0,null);g.dispose();}return javax.imageio.ImageIO.write(b,format==CompressFormat.JPEG?"jpg":"png",out);}catch(java.io.IOException e){return false;}}
public final BufferedImage image;final java.util.Map<ColorFilter,BufferedImage> variants=new java.util.HashMap<>();public enum Config{ARGB_8888}public Bitmap(BufferedImage b){int type=b.getColorModel().hasAlpha()?BufferedImage.TYPE_INT_ARGB_PRE:BufferedImage.TYPE_INT_RGB;if(b.getType()==type)image=b;else{image=new BufferedImage(b.getWidth(),b.getHeight(),type);java.awt.Graphics2D g=image.createGraphics();g.setComposite(java.awt.AlphaComposite.Src);g.drawImage(b,0,0,null);g.dispose();}}public int getWidth(){return image.getWidth();}public int getHeight(){return image.getHeight();}public int getAllocationByteCount(){return getWidth()*getHeight()*4;}public static Bitmap createBitmap(int[] pixels,int w,int h,Config c){BufferedImage b=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB_PRE);b.setRGB(0,0,w,h,pixels,0,w);return new Bitmap(b);}static int channel(float v){return Math.max(0,Math.min(255,Math.round(v)));}
 BufferedImage filtered(ColorFilter f){if(!(f instanceof ColorMatrixColorFilter))return image;return variants.computeIfAbsent(f,key->{float[] m=((ColorMatrixColorFilter)key).matrix;int w=getWidth(),h=getHeight();int[] pixels=image.getRGB(0,0,w,h,null,0,w);for(int i=0;i<pixels.length;i++){int c=pixels[i],a=c>>>24,r=c>>16&255,g=c>>8&255,b=c&255;pixels[i]=(channel(m[15]*r+m[16]*g+m[17]*b+m[18]*a+m[19])<<24)|(channel(m[0]*r+m[1]*g+m[2]*b+m[3]*a+m[4])<<16)|(channel(m[5]*r+m[6]*g+m[7]*b+m[8]*a+m[9])<<8)|channel(m[10]*r+m[11]*g+m[12]*b+m[13]*a+m[14]);}BufferedImage out=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB_PRE);out.setRGB(0,0,w,h,pixels,0,w);return out;});}}
